package com.paymentplatform.distribution_service.domain;
import com.paymentplatform.distribution_service.client.DependencyClient;import com.paymentplatform.distribution_service.api.ApiException;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.security.oauth2.jwt.JwtDecoder;import org.springframework.stereotype.Service;import tools.jackson.databind.*;import java.time.*;import java.util.*;
@Service public class CashWorkflow {
 private final CashStore store;private final DependencyClient client;private final JwtDecoder decoder;private final ObjectMapper json;private final String tokens,accounts;private final boolean enabled;
 public CashWorkflow(CashStore store,DependencyClient client,JwtDecoder decoder,ObjectMapper json,@Value("${boodoo.cash.tokens-json}") String tokens,@Value("${boodoo.cash.accounts-json}") String accounts,@Value("${boodoo.cash.zero-fee-enabled:false}") boolean enabled){this.store=store;this.client=client;this.decoder=decoder;this.json=json;this.tokens=tokens;this.accounts=accounts;this.enabled=enabled;}
 public record Request(@NotNull UUID walletId,@NotBlank @Pattern(regexp="IN|OUT") String direction,@NotNull @Positive Long amount,@NotBlank @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9._:-]{0,127}") String evidence,@Pattern(regexp="[0-9]{6}") String pin){@Override public String toString(){return "CashRequest[REDACTED]";}}
 private String bearer(String tenant){try{String token=DependencyClient.text(json.readTree(tokens),tenant);var jwt=decoder.decode(token);if(!tenant.equals(jwt.getClaimAsString("integrator_id"))||!"distribution-service".equals(jwt.getSubject())||!"service".equals(jwt.getClaims().get("actor_type")))throw DependencyClient.unavailable();return token;}catch(Exception e){throw DependencyClient.unavailable();}}
 public CashStore.Row request(String tenant,String actor,String key,Request request){if(!enabled)throw DependencyClient.unavailable();var row=store.begin(tenant,actor,key,request);if(!row.state().equals("NEW"))return row;UUID lease=store.claim(tenant,row.id());if(lease==null)return store.get(tenant,row.id());try{
  String token=bearer(tenant);var wallet=wallet(row,token);UUID account=UUID.fromString(DependencyClient.text(json.readTree(accounts),tenant));var metadata=client.get("ledger","/internal/v1/accounts/"+account,token);require(metadata,200);if(!account.equals(DependencyClient.uuid(metadata.body(),"id"))||!"ASSET".equals(DependencyClient.text(metadata.body(),"type"))||!"XOF".equals(DependencyClient.text(metadata.body(),"currency")))throw DependencyClient.unavailable();
  if(row.direction().equals("OUT")){if(request.pin()==null)throw CashStore.error(HttpStatus.BAD_REQUEST,"PIN_REQUIRED");var pin=client.post("identity","/v1/customers/"+DependencyClient.uuid(wallet,"customerId")+"/pin/verify",Map.of("pin",request.pin()),null,token);if(pin.status()==422||pin.status()==429)throw CashStore.error(HttpStatus.UNPROCESSABLE_CONTENT,"PIN_REJECTED");require(pin,204);}
  var context=new CashStore.Context(DependencyClient.uuid(wallet,"customerId"),DependencyClient.uuid(wallet,"ledgerAccountId"),account,null,Instant.now().plusSeconds(300));return store.save(tenant,row.id(),lease,"REQUESTED",context,null);
 }finally{store.release(tenant,row.id(),lease);}}
 public CashStore.Row approve(String tenant,String checker,UUID id){store.approve(tenant,checker,id);return execute(tenant,id);}
 private CashStore.Row execute(String tenant,UUID id){var row=store.get(tenant,id);if(Set.of("ACCOUNTED","DISBURSED").contains(row.state()))return row;UUID lease=store.claim(tenant,id);if(lease==null)return row;try{
  row=store.get(tenant,id);String token=bearer(tenant);var c=row.context();
  if(row.state().equals("APPROVED")){
   ensureFuture(c.expiresAt());var current=wallet(row,token);if(!c.customer().equals(DependencyClient.uuid(current,"customerId"))||!c.walletAccount().equals(DependencyClient.uuid(current,"ledgerAccountId")))throw DependencyClient.unavailable();
   if(row.direction().equals("OUT")){
    UUID evaluation=UUID.randomUUID();var risk=client.post("risk","/internal/v1/evaluations",Map.of("id",evaluation,"reference",id,"customerId",c.customer(),"amount",row.amount(),"currency","XOF"),null,token);require(risk,201);if(!id.equals(DependencyClient.uuid(risk.body(),"reference"))||!evaluation.equals(DependencyClient.uuid(risk.body(),"id"))||!c.customer().equals(DependencyClient.uuid(risk.body(),"customerId"))||DependencyClient.integer(risk.body(),"amount")!=row.amount()||!"ALLOW".equals(DependencyClient.text(risk.body(),"outcome")))throw DependencyClient.unavailable();
    Instant riskExpiry=Instant.parse(DependencyClient.text(risk.body(),"expiresAt"));ensureFuture(riskExpiry);if(riskExpiry.isBefore(c.expiresAt()))c=new CashStore.Context(c.customer(),c.walletAccount(),c.settlementAccount(),c.reservation(),riskExpiry);
    var allowance=client.post("limits","/internal/v1/reservations",Map.of("reference",id,"customerId",c.customer(),"amount",row.amount(),"currency","XOF"),"cash-"+id,token);require(allowance,201);
    if(!id.equals(DependencyClient.uuid(allowance.body(),"reference"))||!c.customer().equals(DependencyClient.uuid(allowance.body(),"customerId"))||DependencyClient.integer(allowance.body(),"amount")!=row.amount()||!"RESERVED".equals(DependencyClient.text(allowance.body(),"status")))throw DependencyClient.unavailable();
    Instant expiry=Instant.parse(DependencyClient.text(allowance.body(),"expiresAt"));if(expiry.isAfter(c.expiresAt()))expiry=c.expiresAt();c=new CashStore.Context(c.customer(),c.walletAccount(),c.settlementAccount(),DependencyClient.uuid(allowance.body(),"id"),expiry);
   }
   row=store.save(tenant,id,lease,"POSTING",c,null);
  }
  if(row.state().equals("POSTING")){
   var receipt=client.get("ledger","/internal/v1/journals/by-reference?reference="+id,token);
   if(receipt.status()==404){ensureFuture(row.context().expiresAt());var current=wallet(row,token);if(!row.context().walletAccount().equals(DependencyClient.uuid(current,"ledgerAccountId")))throw DependencyClient.unavailable();receipt=client.post("ledger","/internal/v1/journals",Map.of("reference",id,"entries",entries(row)),"cash-"+id,token);require(receipt,201);}else require(receipt,200);
   verify(row,receipt.body());row=store.save(tenant,id,lease,"POSTED",row.context(),DependencyClient.uuid(receipt.body(),"id"));
  }
  if(row.state().equals("POSTED")){if(row.direction().equals("OUT")){var result=client.post("limits","/internal/v1/reservations/"+row.context().reservation()+"/confirm",null,null,token);require(result,200);if(!row.context().reservation().equals(DependencyClient.uuid(result.body(),"id"))||!"CONFIRMED".equals(DependencyClient.text(result.body(),"status")))throw DependencyClient.unavailable();}row=store.save(tenant,id,lease,"ACCOUNTED",row.context(),row.journal());}
  return row;
 }catch(ApiException|IllegalArgumentException error){return store.get(tenant,id);}finally{store.release(tenant,id,lease);}}
 private JsonNode wallet(CashStore.Row row,String token){var result=client.get("wallet","/internal/v1/wallets/"+row.wallet()+"/operational-state",token);require(result,200);Instant checked=Instant.parse(DependencyClient.text(result.body(),"checkedAt"));if(!row.wallet().equals(DependencyClient.uuid(result.body(),"walletId"))||!"ACTIVE".equals(DependencyClient.text(result.body(),"status"))||!DependencyClient.bool(result.body(),"eligible")||!"XOF".equals(DependencyClient.text(result.body(),"currency"))||checked.isBefore(Instant.now().minusSeconds(30))||checked.isAfter(Instant.now().plusSeconds(30)))throw DependencyClient.unavailable();return result.body();}
 private List<Map<String,Object>> entries(CashStore.Row r){return List.of(Map.of("accountId",r.context().settlementAccount(),"side",r.direction().equals("IN")?"DEBIT":"CREDIT","amount",r.amount()),Map.of("accountId",r.context().walletAccount(),"side",r.direction().equals("IN")?"CREDIT":"DEBIT","amount",r.amount()));}
 private void verify(CashStore.Row row,JsonNode receipt){if(!row.id().equals(DependencyClient.uuid(receipt,"reference"))||!"XOF".equals(DependencyClient.text(receipt,"currency")))throw DependencyClient.unavailable();var actual=receipt.get("entries");if(actual==null||!actual.isArray()||actual.size()!=2)throw DependencyClient.unavailable();Set<String> expected=new HashSet<>();for(var e:entries(row))expected.add(e.get("accountId")+":"+e.get("side")+":"+e.get("amount"));for(var e:actual)if(!expected.remove(DependencyClient.uuid(e,"accountId")+":"+DependencyClient.text(e,"side")+":"+DependencyClient.integer(e,"amount")))throw DependencyClient.unavailable();if(!expected.isEmpty())throw DependencyClient.unavailable();}
 private void ensureFuture(Instant expiry){if(!expiry.isAfter(Instant.now().plusSeconds(5)))throw DependencyClient.unavailable();}
 private void require(DependencyClient.Reply reply,int status){if(reply.status()!=status)throw DependencyClient.unavailable();}
}
